def write_full_replacement(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def verify_oia_023_contract(path: Path) -> None:
    if not path.exists():
        raise SystemExit(
            "[FAIL] OIA-023 production module is missing. "
            "Install and pass OIA-023 first."
        )
    text = path.read_text(encoding="utf-8")
    required = (
        'SCHEMA_VERSION = "OIA-023"',
        'ENGINE_ID = "OIA-023"',
        "SESSION_POLICY_ID",
        "oracle.qualified-research-worker-session-manifest.v1",
        'SESSION_READY = "session_ready"',
        'SESSION_ENTRY_READY = "session_entry_ready"',
        "DEFAULT_SESSION_DIRECTORY",
        "class OracleQualifiedResearchWorkerSessionEntry:",
        "class OracleQualifiedResearchWorkerSessionManifest:",
        "class OracleQualifiedResearchWorkerSessionManifestBuilder:",
        "session_sequence",
        "source_activation_hash",
        "source_claim_hash",
        "source_manifest_hash",
        "source_batch_hash",
        "session_entry_hash",
        "session_hash",
        "research_execution_allowed",
        "qseries_handoff_allowed",
        "session_artifact_persistence_allowed",
    )
    missing = [token for token in required if token not in text]
    if missing:
        raise SystemExit(
            f"[FAIL] Actual OIA-023 production contract mismatch: {missing}"
        )


def update_package_initializer(path: Path) -> None:
    if not path.exists():
        raise SystemExit(
            f"[FAIL] Analytics package initializer is missing: {path}"
        )
    original = path.read_text(encoding="utf-8")
    updated = original
    marker = (
        "from .oracle_qualified_research_worker_session_readiness_gate import"
    )
    if marker not in updated:
        updated = updated.rstrip() + "\n\n" + INIT_IMPORT_BLOCK.strip() + "\n"

    if "__all__" in updated:
        missing_exports = [
            name
            for name in INIT_EXPORTS
            if f'"{name}"' not in updated and f"'{name}'" not in updated
        ]
        if missing_exports:
            export_lines = "\n".join(
                f'    "{name}",' for name in missing_exports
            )
            updated = (
                updated.rstrip()
                + "\n\n__all__ = [\n"
                + export_lines
                + "\n] + __all__\n"
            )

    if updated == original:
        print(f"[OK] PACKAGE EXPORTS ALREADY PRESENT: {path.resolve()}")
        return

    path.write_text(updated, encoding="utf-8", newline="\n")
    print(f"[OK] PACKAGE EXPORT UPDATE: {path.resolve()}")


def main() -> int:
    root = Path.cwd()
    analytics = root / "qseries_v2" / "oracle_intelligence" / "analytics"
    dependency = (
        analytics
        / "oracle_qualified_research_worker_session_manifest_builder.py"
    )
    production = (
        analytics
        / "oracle_qualified_research_worker_session_readiness_gate.py"
    )
    test = (
        root
        / "test_oia_024_oracle_qualified_research_worker_session_readiness_gate.py"
    )
    initializer = analytics / "__init__.py"

    print("========================================")
    print(" OIA-024 INSTALLER")
    print(" QUALIFIED RESEARCH WORKER")
    print(" SESSION READINESS GATE")
    print("========================================")

    verify_oia_023_contract(dependency)
    print("[OK] Actual OIA-023 worker session contract verified")

    write_full_replacement(production, MODULE_SOURCE)
    write_full_replacement(test, TEST_SOURCE)
    update_package_initializer(initializer)

    ast.parse(MODULE_SOURCE, filename=str(production))
    ast.parse(TEST_SOURCE, filename=str(test))
    ast.parse(initializer.read_text(encoding="utf-8"), filename=str(initializer))
    print("[OK] OIA-024 production, package, and test syntax verified")

    completed = subprocess.run(
        [sys.executable, str(test)],
        cwd=root,
        check=False,
    )
    if completed.returncode != 0:
        raise SystemExit(completed.returncode)

    print("[OK] OIA-024 test executed successfully")
    print(
        "[DONE] OIA-024 Oracle Qualified Research "
        "Worker Session Readiness Gate installed"
    )
    print()
    print("Verify the current research worker session with:")
    print(
        "python -m "
        "qseries_v2.oracle_intelligence.analytics."
        "oracle_qualified_research_worker_session_readiness_gate"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
